#include <string>

using namespace std;

class Solution {
public:
    int longestCommonPrefix(string s, string t) {
        int n = s.size(), m = t.size();
        int i = 0, j = 0;
        bool removed = false;
        while (i < n && j < m) {
            if (s[i] == t[j]) {
                i++;
                j++;
            } else if (!removed) {
                removed = true;
                i++;
            } else {
                break;
            }
        }
        return j;
    }
};

class Solution {
    public int longestCommonPrefix(String s, String t) {
        int n = s.length(), m = t.length();
        int i = 0, j = 0;
        boolean removed = false;
        while (i < n && j < m) {
            if (s.charAt(i) == t.charAt(j)) {
                i++;
                j++;
            } else if (!removed) {
                removed = true;
                i++;
            } else {
                break;
            }
        }
        return j;
    }
}

