var longestCommonPrefix = function(s, t) {
    const n = s.length, m = t.length;
    let i = 0, j = 0;
    let removed = false;
    while (i < n && j < m) {
        if (s[i] === t[j]) {
            i++;
            j++;
        } else if (!removed) {
            removed = true;
            i++;
        } else {
            break;
        }
    }
    return j;
};
